/// A series' rule (VTI-EVT-190): JSCalendar's RecurrenceRule, limited to these
/// members. Exactly one of `count` and `until` ends it. A responder MUST refuse any
/// other member.
class EventRecurrenceRule {
  const EventRecurrenceRule({
    required this.frequency,
    this.interval,
    this.byDay,
    this.byMonthDay,
    this.count,
    this.until,
  });

  /// Read this payload from a decoded JSON object.
  factory EventRecurrenceRule.fromJson(Map<String, dynamic> json) =>
      EventRecurrenceRule(
        frequency: EventRecurrenceFrequency(json['frequency'] as String),
        interval: json['interval'] as int?,
        byDay: json['byDay'] == null
            ? null
            : (json['byDay'] as List<dynamic>)
                .map((e) =>
                    EventRecurrenceDay.fromJson(e as Map<String, dynamic>))
                .toList(),
        byMonthDay: json['byMonthDay'] == null
            ? null
            : (json['byMonthDay'] as List<dynamic>)
                .map((e) => e as int)
                .toList(),
        count: json['count'] as int?,
        until: json['until'] as String?,
      );

  final EventRecurrenceFrequency frequency;

  /// Every so many periods. Absent means 1.
  final int? interval;

  /// The weekdays it falls on.
  final List<EventRecurrenceDay>? byDay;

  /// The days of the month it falls on; negative counts from the end. Never 0.
  final List<int>? byMonthDay;

  /// How many occurrences in all.
  final int? count;

  /// The last local date-time an occurrence may start at, in the series' zone.
  final LocalDateTime? until;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'frequency': frequency.value,
        if (interval != null) 'interval': interval!,
        if (byDay != null) 'byDay': byDay!.map((e) => e.toJson()).toList(),
        if (byMonthDay != null) 'byMonthDay': byMonthDay!,
        if (count != null) 'count': count!,
        if (until != null) 'until': until!,
      };
}

/// A change to one occurrence, kept against its original start (VTI-EVT-193). Members
