/// What makes an event a series (VTI-EVT-190 – 193): one rule, and the changes to
/// single occurrences keyed by their original starts.
class EventRecurrence {
  const EventRecurrence({
    required this.recurrenceRules,
    this.recurrenceOverrides,
  });

  /// Read this payload from a decoded JSON object.
  factory EventRecurrence.fromJson(Map<String, dynamic> json) =>
      EventRecurrence(
        recurrenceRules: (json['recurrenceRules'] as List<dynamic>)
            .map((e) => EventRecurrenceRule.fromJson(e as Map<String, dynamic>))
            .toList(),
        recurrenceOverrides: json['recurrenceOverrides'] == null
            ? null
            : (json['recurrenceOverrides'] as Map<String, dynamic>).map(
                (k, v) => MapEntry(
                    k,
                    EventOccurrenceOverride.fromJson(
                        v as Map<String, dynamic>))),
      );

  /// The series' rule, as JSCalendar carries it — an array of exactly one here.
  final List<EventRecurrenceRule> recurrenceRules;

  /// Changes to single occurrences, keyed by each one's original start.
  final Map<String, EventOccurrenceOverride>? recurrenceOverrides;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'recurrenceRules': recurrenceRules.map((e) => e.toJson()).toList(),
        if (recurrenceOverrides != null)
          'recurrenceOverrides':
              recurrenceOverrides!.map((k, v) => MapEntry(k, v.toJson())),
      };
}

