  /// Whether the event counts toward attendance (VTI-EVT-180). Absent: its calendar's
  /// default.
  final bool? countsAttendance;

  /// A badge offered to a member when their check-in is recorded, for them to accept
  /// (VTI-EVT-186).
  final BadgeId? attendanceBadge;

  /// Present on a series (VTI-EVT-190).
  final EventRecurrence? recurrence;

  /// On a series: what a registration is for (VTI-EVT-194). Absent on a series means
  /// `series`.
  final EventRegistrationScope? registrationScope;

  /// Registration must be identified: persona registrations are refused (VTI-EVT-231).
  /// Absent means false.
  final bool? identified;

  /// On an `anonymous` event (VTI-EVT-213).
  final EventAnonymity? anonymity;

  /// The series this one continues, or that continues it (VTI-EVT-197).
  final List<EventSeriesLink>? relatedTo;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'eventId': eventId,
        'calendarId': calendarId,
        'kind': kind.value,
        'status': status.value,
        'title': title,
        if (description != null) 'description': description!,
        'when': when.toJson(),
        if (placeSummary != null) 'placeSummary': placeSummary!,
        if (access != null) 'access': access!.toJson(),
        'audience': audience.toJson(),
        'registration': registration.toJson(),
        'roster': roster.value,
        if (showCount != null) 'showCount': showCount!,
        if (countThreshold != null) 'countThreshold': countThreshold!,
        'listed': listed,
        if (accessibility != null) 'accessibility': accessibility!.toJson(),
        if (suggestedReminderMinutes != null)
          'suggestedReminderMinutes': suggestedReminderMinutes!,
        if (hosts != null) 'hosts': hosts!,
        if (goingCount != null) 'goingCount': goingCount!.toJson(),
        if (full != null) 'full': full!,
        'sequence': sequence,
        if (cancelReason != null) 'cancelReason': cancelReason!,
        if (publishedAt != null) 'publishedAt': publishedAt!,
        if (cancelledAt != null) 'cancelledAt': cancelledAt!,
        'createdAt': createdAt,
        'updatedAt': updatedAt,
        if (invite != null) 'invite': invite!.value,
        if (membersMayInvite != null) 'membersMayInvite': membersMayInvite!,
        if (identity != null) 'identity': identity!.toJson(),
        if (guests != null) 'guests': guests!.value,
        if (tickets != null) 'tickets': tickets!,
        if (countsAttendance != null) 'countsAttendance': countsAttendance!,
        if (attendanceBadge != null) 'attendanceBadge': attendanceBadge!,
        if (recurrence != null) 'recurrence': recurrence!.toJson(),
        if (registrationScope != null)
          'registrationScope': registrationScope!.value,
        if (identified != null) 'identified': identified!,
        if (anonymity != null) 'anonymity': anonymity!.toJson(),
        if (relatedTo != null)
          'relatedTo': relatedTo!.map((e) => e.toJson()).toList(),
      };
}

/// Vendor-namespaced extension object per SPEC.md §4.5.1. Each immediate key MUST be a
/// reverse-DNS namespace; structure under each namespace is opaque to the framework.
typedef Ext = Map<String, dynamic>;

/// The success response to a vtc/events/publish/0.2 request. Carried in a Trust Task
/// document whose type is https://trusttasks.org/spec/vtc/events/publish/0.4#response.
class Response {
  const Response({
    required this.event,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory Response.fromJson(Map<String, dynamic> json) => Response(
        event: Event.fromJson(json['event'] as Map<String, dynamic>),
        ext: json['ext'] as Map<String, dynamic>?,
      );

  /// The published event, as its host sees it.
  final Event event;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'event': event.toJson(),
        if (ext != null) 'ext': ext!,
      };
}

/// Publish a draft event. The outer document members are owned by the framework — SPEC
/// §6.3.
class Payload {
  const Payload({
    required this.eventId,
    this.ext,
  });

  /// Read this payload from a decoded JSON object.
  factory Payload.fromJson(Map<String, dynamic> json) => Payload(
        eventId: json['eventId'] as String,
        ext: json['ext'] as Map<String, dynamic>?,
      );

  final EventId eventId;
  final Ext? ext;

  /// Serialize to a JSON-encodable map, omitting absent members.
  Map<String, dynamic> toJson() => <String, dynamic>{
        'eventId': eventId,
        if (ext != null) 'ext': ext!,
      };
}

